exercise.solution:
// JavaScript track — same Prisma schema DSL; Zod validates inputs at the JS boundary.
model LabL06User {
  id       Int    @id @default(autoincrement())
  name     String
  child    LabL06Profile?
  @@map("lab_l06_users")
}

model LabL06Profile {
  id    Int    @id @default(autoincrement())
  title String
  userId Int @unique @map("user_id")
  user LabL06User @relation(fields: [userId], references: [id])
  @@map("lab_l06_profiles")
}

